local Loader = require(script.Parent.Loader)
local module = {}
local _pool = {}
local _nodeModulePool = {}

function module.CreateNode(prefabName)
    local node, nodeModule = Loader.GetPrefab(prefabName):Clone()
    node:SetAttribute("__prefab", prefabName)
    if nodeModule then
        _nodeModulePool[node] = nodeModule
    end
    return node
end

function module.GetNode(prefabName, ...)
    if _pool[prefabName] and #_pool[prefabName] > 0 then
        local node = table.remove(_pool[prefabName])
        if _nodeModulePool[node] and _nodeModulePool[node].OnNodeGet then
            _nodeModulePool[node].OnNodeGet(_nodeModulePool[node], ...)
        end
        return node
    else
        local prefab = Loader.GetPrefab(prefabName)
        if not prefab then
            warn("[ NezaUI ] Prefab [" .. prefabName .. "] not found")
            return
        end
        local node, nodeModule = prefab:Clone()
        if nodeModule and nodeModule.OnNodeGet then
            nodeModule.OnNodeGet(nodeModule, ...)
            _nodeModulePool[node] = nodeModule
        end
        node:SetAttribute("__prefab", prefabName)
        return node
    end
end

function module.PutNode(node, ...)
    local name = node:GetAttribute("__prefab")
    if not name then
        warn("[ NezaUI ] Node has no prefab name, just destroy it")
        node:Destroy()
        return
    end
    if not node.Parent then
        warn("[ NezaUI ] Node has no parent")
        return
    end
    if not _pool[name] then
        _pool[name] = {}
    end
    node.Parent = nil
    if _nodeModulePool[node] and _nodeModulePool[node].OnNodePut then
        _nodeModulePool[node].OnNodePut(_nodeModulePool[node])
    end
    table.insert(_pool[name], node)
end

return module